/**
 * The client/server contract.
 *
 * Every endpoint lives here so the client and the server can never disagree
 * about a path or a payload shape.
 */
import type { Band, PlayStatus, Probe } from './daily.ts';

export type ErrorRsp = { error: string; status: number };

/** Everything the client needs to draw the game, and nothing more. */
export type PlayerView = {
  day: string;
  /** Human-facing puzzle number, e.g. 322. */
  number: number;
  /** Rooms per side of the mansion. */
  grid: number;
  /** Candles you start the day with. */
  candles: number;
  candlesLeft: number;
  probes: Probe[];
  status: PlayStatus;
  /** Room of the ghost — only sent once the day is over for this player. */
  ghost: number | null;
  streak: number;
  best: number;
  wins: number;
  plays: number;
};

export type BoardEntry = {
  name: string;
  /** Candles used. Lower is better. */
  candles: number;
  isYou: boolean;
};

export type StreakEntry = { name: string; streak: number; isYou: boolean };

export type DayStats = {
  plays: number;
  catches: number;
  catchRate: number;
  avgCandles: number;
};

export type GamePayload = {
  player: PlayerView;
  /** Today's fastest hunters. */
  board: BoardEntry[];
  /** Longest active streaks in this community. */
  streaks: StreakEntry[];
  stats: DayStats;
  username: string | null;
};

export type StateRsp = GamePayload;

export type ProbeReq = { i: number };
export type ProbeRsp = GamePayload & { band: Band | null };

export type ShareRsp = { status: 'posted' | 'already' | 'error'; message: string };

export type Endpoint = (typeof Endpoint)[keyof typeof Endpoint];
export const Endpoint = {
  State: 'api/state',
  Probe: 'api/probe',
  Share: 'api/share',
  OnAppInstall: 'internal/on/app/install',
  OnMenuNewPost: 'internal/on/menu/new-post',
  OnDailyPost: 'internal/on/scheduler/daily-post',
} as const;

export const EndpointMethod = {
  [Endpoint.State]: 'GET',
  [Endpoint.Probe]: 'POST',
  [Endpoint.Share]: 'POST',
  [Endpoint.OnAppInstall]: 'POST',
  [Endpoint.OnMenuNewPost]: 'POST',
  [Endpoint.OnDailyPost]: 'POST',
} as const satisfies { [endpoint: string]: 'GET' | 'POST' };
