/** Thin fetch wrappers around the /api/ endpoints. */
import {
  Endpoint,
  type ErrorRsp,
  type ProbeRsp,
  type ShareRsp,
  type StateRsp,
} from '../shared/api.ts';

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  let rsp: Response;
  try {
    rsp = await fetch(path, {
      ...init,
      headers: { Accept: 'application/json', ...(init?.headers ?? {}) },
    });
  } catch (err) {
    throw Error(`Network error: ${err instanceof Error ? err.message : String(err)}`);
  }

  if (!rsp.ok) {
    const body = (await rsp.json().catch(() => undefined)) as ErrorRsp | undefined;
    throw Error(body?.error ?? `HTTP ${rsp.status} ${rsp.statusText}`);
  }

  return (await rsp.json()) as T;
}

export function fetchState(): Promise<StateRsp> {
  return request<StateRsp>(Endpoint.State);
}

export function postProbe(i: number): Promise<ProbeRsp> {
  return request<ProbeRsp>(Endpoint.Probe, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ i }),
  });
}

export function postShare(): Promise<ShareRsp> {
  return request<ShareRsp>(Endpoint.Share, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: '{}',
  });
}
