/** The expanded game view: the mansion, the candles, the ghost. */
import { GRID, ROOMS, shareText } from '../shared/daily.ts';
import type { GamePayload } from '../shared/api.ts';
import { fetchState, postProbe, postShare } from './api.ts';
import {
  bandEmoji,
  ghostSvg,
  mountArt,
  qs,
  renderHint,
  renderHud,
  renderPanels,
  roomName,
  showToast,
} from './ui.ts';

let payload: GamePayload | null = null;
let busy = false;
/** Rooms painted on the previous frame, so we only animate what is new. */
let painted = new Set<number>();

const grid = qs<HTMLDivElement>('grid');
const overlay = qs<HTMLDivElement>('overlay');
const shareBtn = qs<HTMLButtonElement>('share-btn');
const copyBtn = qs<HTMLButtonElement>('copy-btn');
const closeBtn = qs<HTMLButtonElement>('close-btn');

function buildGrid(): void {
  grid.style.setProperty('--grid', String(GRID));
  for (let i = 0; i < ROOMS; i++) {
    const tile = document.createElement('button');
    tile.type = 'button';
    tile.className = 'tile can-probe';
    tile.dataset['i'] = String(i);
    tile.setAttribute('role', 'gridcell');
    tile.setAttribute('aria-label', `Sweep room ${roomName(i)}`);
    grid.append(tile);
  }
}

function render(next: GamePayload): void {
  const wasFinished = payload !== null && payload.player.status !== 'playing';
  payload = next;
  renderHud(next.player);
  renderHint(next.player);
  renderPanels(next);
  paint();
  if (!wasFinished && next.player.status !== 'playing' && !overlay.classList.contains('hidden')) {
    return; // player already closed the result card
  }
}

function paint(): void {
  const p = payload;
  if (!p) return;

  const readings = new Map<number, number>();
  for (const probe of p.player.probes) readings.set(probe.i, probe.b);

  const done = p.player.status !== 'playing' || p.username === null;
  const fresh = new Set<number>();

  for (let i = 0; i < ROOMS; i++) {
    const tile = grid.children[i] as HTMLButtonElement | undefined;
    if (!tile) continue;
    const band = readings.get(i);

    if (band === undefined) {
      tile.className = done ? 'tile' : 'tile can-probe';
      tile.removeAttribute('data-band');
      tile.disabled = done;
      tile.innerHTML = '';
      tile.setAttribute('aria-label', `Sweep room ${roomName(i)}`);
      continue;
    }

    const isNew = !painted.has(i);
    if (isNew) fresh.add(i);
    tile.className = `tile probed${isNew ? ' fresh' : ''}`;
    tile.dataset['band'] = String(band);
    tile.disabled = true;
    tile.innerHTML = `<span class="glyph">${bandEmoji(band)}</span>`;
    tile.setAttribute('aria-label', `Room ${roomName(i)}: ${bandEmoji(band)}`);
  }

  painted = new Set(readings.keys());

  if (p.player.ghost !== null) {
    const room = grid.children[p.player.ghost] as HTMLButtonElement | undefined;
    const caught = p.player.status === 'caught';
    if (room) {
      room.dataset['band'] = '0';
      room.innerHTML = `<span class="ghost-mark" style="opacity:${caught ? 1 : 0.55}">${ghostSvg()}</span>`;
    }
  }

  if (fresh.size > 0) {
    for (const i of fresh) grid.children[i]?.classList.add('fresh');
  }
}

async function sweep(i: number, tile: HTMLButtonElement): Promise<void> {
  const p = payload;
  if (!p || busy) return;
  if (p.player.status !== 'playing' || p.username === null) return;
  if (p.player.probes.some(probe => probe.i === i)) return;
  if (p.player.candlesLeft <= 0) return;

  busy = true;
  tile.classList.add('sweeping');
  try {
    const rsp = await postProbe(i);
    render(rsp);
    if (rsp.player.status !== 'playing') window.setTimeout(() => showResult(), 460);
  } catch (err) {
    showToast(err instanceof Error ? err.message : 'The candle blew out. Try again.');
    tile.classList.remove('sweeping');
  } finally {
    busy = false;
  }
}

function showResult(): void {
  const p = payload;
  if (!p) return;
  const { status, probes, candles, ghost, number, streak } = p.player;
  const caught = status === 'caught';

  mountArt(qs<HTMLDivElement>('ghost-art'), !caught);
  qs('result-title').textContent = caught ? 'Caught it. 👻' : 'It slipped away. 💨';

  const streakLine = caught
    ? streak > 1
      ? ` — 🔥 streak <b>${streak}</b>.`
      : '.'
    : '';

  qs('result-text').innerHTML = caught
    ? `You cornered the ghost in <b>${probes.length}/${candles}</b> candles${streakLine} ` +
      `Ghost #${number + 1} appears tomorrow at 00:00 UTC.`
    : ghost !== null
      ? `All ${candles} candles burned out. It was hiding in <b>${roomName(ghost)}</b>. ` +
        `Ghost #${number + 1} appears tomorrow at 00:00 UTC.`
      : `All ${candles} candles burned out.`;

  shareBtn.disabled = false;
  shareBtn.textContent = 'Share to thread';
  overlay.classList.remove('hidden');
}

async function share(): Promise<void> {
  shareBtn.disabled = true;
  shareBtn.textContent = 'Posting…';
  try {
    const rsp = await postShare();
    showToast(rsp.message);
    shareBtn.textContent = rsp.status === 'error' ? 'Share to thread' : 'Shared ✓';
  } catch (err) {
    showToast(err instanceof Error ? err.message : 'Could not post that comment.');
    shareBtn.textContent = 'Share to thread';
  } finally {
    shareBtn.disabled = false;
  }
}

async function copy(): Promise<void> {
  const p = payload;
  if (!p) return;
  const text = shareText({
    day: p.player.day,
    probes: p.player.probes,
    status: p.player.status,
    streak: p.player.streak,
  }).replaceAll(/^>!(.*)!$/gm, '$1');
  if (await writeClipboard(text)) {
    showToast('Result copied. Paste it anywhere.');
  } else {
    showToast('Clipboard is blocked here — post it to the thread instead.');
  }
}

/** Clipboard, with a legacy fallback for locked-down webviews. */
async function writeClipboard(text: string): Promise<boolean> {
  try {
    if (navigator.clipboard && window.isSecureContext) {
      await navigator.clipboard.writeText(text);
      return true;
    }
  } catch {
    // fall through to execCommand
  }
  try {
    const area = document.createElement('textarea');
    area.value = text;
    area.setAttribute('readonly', '');
    area.style.position = 'fixed';
    area.style.top = '-1000px';
    document.body.append(area);
    area.select();
    const ok = document.execCommand('copy');
    area.remove();
    return ok;
  } catch {
    return false;
  }
}

async function init(): Promise<void> {
  buildGrid();
  mountArt(qs<HTMLDivElement>('ghost-art'));
  grid.addEventListener('click', event => {
    const tile = (event.target as HTMLElement | null)?.closest('button.tile');
    if (!(tile instanceof HTMLButtonElement)) return;
    void sweep(Number(tile.dataset['i']), tile);
  });
  shareBtn.addEventListener('click', () => void share());
  copyBtn.addEventListener('click', () => void copy());
  closeBtn.addEventListener('click', () => overlay.classList.add('hidden'));

  try {
    render(await fetchState());
  } catch (err) {
    showToast(err instanceof Error ? err.message : 'Could not reach the mansion.');
    return;
  }

  const p = payload;
  if (!p) return;
  if (p.username === null) {
    qs('hint').innerHTML =
      '<strong>Sign in to Reddit</strong> to hunt today’s ghost — it is the same ghost for everyone.';
    return;
  }
  if (p.player.status !== 'playing') showResult();
}

void init();
