/**
 * The rules of Ghost of the Day.
 *
 * Everything in this file is *isomorphic*: the client and the server both import
 * it. The server is authoritative, the client uses it to render.
 *
 * The whole daily puzzle is derived from the UTC date alone (a seeded PRNG), so
 * every Redditor in the world gets the same mansion, the same ghost, and the
 * same number of candles — with nothing stored to make it true.
 */

/** Mansion is a square grid of rooms. */
export const GRID = 7;
/** Rooms in the mansion. */
export const ROOMS = GRID * GRID;
/** Candle probes allowed per day. Tuned so thinking players usually win. */
export const CANDLES = 6;
/** Day #1 of the puzzle. */
export const EPOCH_DAY = '2026-01-01';

/** How loud the ghost's presence is in a room. 0 = the ghost is right there. */
export type Band = 0 | 1 | 2 | 3;
/** One candle sweep: room index + the reading it returned. */
export type Probe = { i: number; b: Band };
export type PlayStatus = 'playing' | 'caught' | 'fled';

export type BandInfo = {
  label: string;
  blurb: string;
  emoji: string;
  /** CSS custom property name used by the client for tinting. */
  tone: string;
};

/** Distance bands, in order. Distances are Manhattan steps through the mansion. */
export const BANDS: readonly BandInfo[] = [
  {
    label: 'IT IS HERE',
    blurb: 'The candle gutters. Something is in this room.',
    emoji: '👻',
    tone: 'here',
  },
  {
    label: 'SCORCHING',
    blurb: 'The air is thick and freezing at once. Very close.',
    emoji: '🔥',
    tone: 'hot',
  },
  {
    label: 'WARM',
    blurb: 'A draught from a nearby room. Warm-ish.',
    emoji: '🌡️',
    tone: 'warm',
  },
  {
    label: 'FREEZING',
    blurb: 'Nothing but dust and cold stone here.',
    emoji: '🧊',
    tone: 'cold',
  },
];

/** Upper distance bound for each band (index 0..3). */
const BAND_MAX = [0, 3, 6] as const;

export function bandInfo(b: Band): BandInfo {
  const info = BANDS[b];
  if (!info) throw Error(`bad band ${b}`);
  return info;
}

/** Manhattan distance between two rooms. */
export function distance(a: number, b: number): number {
  return Math.abs(Math.floor(a / GRID) - Math.floor(b / GRID)) + Math.abs((a % GRID) - (b % GRID));
}

/** Bucket a distance into a reading. */
export function bandOfDistance(d: number): Band {
  if (d <= BAND_MAX[0]) return 0;
  if (d <= BAND_MAX[1]) return 1;
  if (d <= BAND_MAX[2]) return 2;
  return 3;
}

/** The reading you get from sweeping `cell` when the ghost is in `ghost`. */
export function reading(cell: number, ghost: number): Band {
  return bandOfDistance(distance(cell, ghost));
}

// ---------------------------------------------------------------------------
// Dates. Every day boundary is UTC so Tokyo and Paris get the same ghost.
// ---------------------------------------------------------------------------

/** UTC calendar day as `YYYY-MM-DD`. */
export function utcDay(date: Date = new Date()): string {
  return date.toISOString().slice(0, 10);
}

/** Shift a `YYYY-MM-DD` day by `n` days (negative goes back). */
export function addDays(day: string, n: number): string {
  const ms = parseDay(day) + n * 86_400_000;
  return new Date(ms).toISOString().slice(0, 10);
}

/** Day number shown to players, starting at 1. */
export function dayNumber(day: string): number {
  return Math.floor((parseDay(day) - parseDay(EPOCH_DAY)) / 86_400_000) + 1;
}

function parseDay(day: string): number {
  const [y, m, d] = day.split('-').map(Number);
  return Date.UTC(y ?? 1970, (m ?? 1) - 1, d ?? 1);
}

// ---------------------------------------------------------------------------
// Seeded randomness: same day in, same ghost out. Stored nowhere.
// ---------------------------------------------------------------------------

function hash32(text: string): number {
  let h = 2166136261 >>> 0;
  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return h >>> 0;
}

function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Which room the ghost hides in on a given day. Deterministic and public. */
export function ghostRoom(day: string): number {
  const rand = mulberry32(hash32(`ghost-of-the-day:v1:${day}`));
  return Math.floor(rand() * ROOMS);
}

// ---------------------------------------------------------------------------
// Sharing
// ---------------------------------------------------------------------------

/**
 * The Wordle-style spoiler-free result grid: 7 rows of 7 emoji showing where you
 * swept and how loud the ghost was, without revealing anything you did not earn.
 */
export function resultGrid(probes: readonly Probe[]): string {
  const cells = new Array<string>(ROOMS).fill('⬛');
  for (const p of probes) {
    const info = BANDS[p.b];
    if (info && p.i >= 0 && p.i < ROOMS) cells[p.i] = info.emoji;
  }
  const rows: string[] = [];
  for (let r = 0; r < GRID; r++) {
    rows.push(cells.slice(r * GRID, r * GRID + GRID).join(''));
  }
  return rows.join('\n');
}

export type ShareInput = {
  day: string;
  probes: readonly Probe[];
  status: PlayStatus;
  streak: number;
};

/** Full comment text posted when a player taps "Share to thread". */
export function shareText(input: ShareInput): string {
  const used = input.probes.length;
  const head = `👻 **Ghost of the Day #${dayNumber(input.day)}**`;
  const tail =
    input.status === 'caught'
      ? used === 1
        ? `Caught it on the first sweep. I am never playing again. 🕯️✨`
        : `Caught in ${used}/${CANDLES} candles 🕯️ · 🔥 streak ${input.streak}`
      : `The ghost slipped away. All ${CANDLES} candles burned out 💨`;
  // Grid stays behind a Reddit spoiler so late players can still play the day.
  const grid = resultGrid(input.probes)
    .split('\n')
    .map(line => `>!${line}!<`)
    .join('\n');
  return [`${head}`, '', grid, '', tail, '', '#GhostOfTheDay'].join('\n');
}
