/** Shared DOM helpers and renderers for the splash and the game. */
import {
  BANDS,
  CANDLES,
  GRID,
  type PlayStatus,
  type Probe,
} from '../shared/daily.ts';
import type { BoardEntry, GamePayload, PlayerView, StreakEntry } from '../shared/api.ts';

export function qs<T extends HTMLElement>(id: string): T {
  const el = document.getElementById(id);
  if (!el) throw Error(`missing #${id}`);
  return el as T;
}

export function roomName(i: number): string {
  const col = String.fromCharCode(65 + (i % GRID));
  const row = Math.floor(i / GRID) + 1;
  return `${col}${row}`;
}

let ghostSvgCount = 0;

/** The mascot. Inline SVG so it works inside Reddit's CSP with no requests. */
export function ghostSvg(): string {
  const id = `ghost-grad-${ghostSvgCount++}`;
  return `<svg viewBox="0 0 64 64" aria-hidden="true" focusable="false">
  <defs>
    <linearGradient id="${id}" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#ffffff"/>
      <stop offset="1" stop-color="#c6adff"/>
    </linearGradient>
  </defs>
  <path d="M32 4C19 4 11 14 11 28v24c0 2.2 2.2 3.4 3.9 2.2l4.6-3.7 4.4 4.5c1 1 2.6 1 3.6 0L32 50.8l4.5 4.2c1 1 2.6 1 3.6 0l4.4-4.5 4.6 3.7c1.7 1.2 3.9 0 3.9-2.2V28C53 14 45 4 32 4z" fill="url(#${id})"/>
  <ellipse cx="23.5" cy="27" rx="3.7" ry="4.8" fill="#221041"/>
  <ellipse cx="40.5" cy="27" rx="3.7" ry="4.8" fill="#221041"/>
  <ellipse cx="25" cy="25.2" rx="1.3" ry="1.7" fill="#ffffff" opacity="0.92"/>
  <ellipse cx="42" cy="25.2" rx="1.3" ry="1.7" fill="#ffffff" opacity="0.92"/>
  <ellipse cx="32" cy="40" rx="4.4" ry="2.6" fill="#3b1f66" opacity="0.55"/>
</svg>`;
}

export function mountArt(target: HTMLElement, gone = false): void {
  target.classList.toggle('gone', gone);
  target.innerHTML = ghostSvg();
}

let toastTimer: number | undefined;

export function showToast(message: string): void {
  const toast = qs<HTMLDivElement>('toast');
  toast.textContent = message;
  toast.classList.add('show');
  if (toastTimer) window.clearTimeout(toastTimer);
  toastTimer = window.setTimeout(() => toast.classList.remove('show'), 2800);
}

export function renderHud(player: PlayerView): void {
  qs('dayno').textContent = `#${player.number}`;

  const candles = qs<HTMLDivElement>('candles');
  const spent = player.candles - player.candlesLeft;
  let html = '';
  for (let i = 0; i < CANDLES; i++) {
    html += `<span class="${i < spent ? 'spent' : ''}">🕯️</span>`;
  }
  candles.innerHTML = html;
  candles.setAttribute(
    'aria-label',
    `${player.candlesLeft} of ${CANDLES} candles left`,
  );

  const streak = qs<HTMLDivElement>('streak');
  const alive = player.streak > 0;
  streak.textContent = `🔥 ${player.streak}`;
  streak.classList.toggle('idle', !alive);
  streak.title = alive
    ? `Caught ${player.streak} day${player.streak === 1 ? '' : 's'} in a row`
    : 'No streak yet — catch it today to start one';
}

export function renderHint(player: PlayerView): void {
  const hint = qs('hint');
  const ghost = player.ghost;
  if (player.status === 'caught') {
    hint.innerHTML =
      `Caught it in <strong>${player.probes.length}/${player.candles}</strong> candles. ` +
      `New ghost tomorrow at 00:00 UTC.`;
    return;
  }
  if (player.status === 'fled') {
    hint.innerHTML =
      ghost === null
        ? `The candles burned out. The ghost is still in there.`
        : `The candles burned out. It was hiding in <strong>${roomName(ghost)}</strong> all along.`;
    return;
  }
  hint.innerHTML =
    player.probes.length === 0
      ? `Sweep a room with your candle. <strong>🔥 scorching</strong> means close, ` +
        `<strong>🧊 freezing</strong> means far. ${player.candles} candles, one ghost.`
      : `<strong>${player.candlesLeft}</strong> candle${player.candlesLeft === 1 ? '' : 's'} left. ` +
        `Narrow it down: every sweep scores the same mansion.`;
}

export function renderPanels(payload: GamePayload): void {
  const board = qs<HTMLOListElement>('board-list');
  const streaks = qs<HTMLOListElement>('streak-list');

  board.innerHTML = payload.board.length
    ? payload.board.map((entry, i) => listItem(i, entry.name, `${entry.candles} 🕯️`, entry.isYou)).join('')
    : `<li class="empty">Nobody yet. Be the first catch.</li>`;

  streaks.innerHTML = payload.streaks.length
    ? payload.streaks.map((entry, i) => listItem(i, entry.name, `${entry.streak} 🔥`, entry.isYou)).join('')
    : `<li class="empty">No streaks yet.</li>`;

  qs('stat-plays').textContent = String(payload.stats.plays);
  qs('stat-rate').textContent =
    payload.stats.plays > 0 ? `${Math.round(payload.stats.catchRate * 100)}%` : '—';
  qs('stat-avg').textContent =
    payload.stats.catches > 0 ? payload.stats.avgCandles.toFixed(1) : '—';
}

function listItem(rank: number, name: string, score: string, isYou: boolean): string {
  // Your own row is highlighted rather than labelled, so the name never truncates.
  return `<li class="${isYou ? 'you' : ''}"${isYou ? ' title="you"' : ''}>
    <span class="rank">${rank + 1}</span>
    <span class="name">${escapeHtml(name)}</span>
    <span class="score">${score}</span>
  </li>`;
}

export function escapeHtml(text: string): string {
  return text
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;');
}

/** How loud was the reading, as a short label. */
export function probeLabel(probe: Probe): string {
  const info = BANDS[probe.b];
  return info ? info.label : '';
}

export function bandEmoji(b: number): string {
  const info = BANDS[b];
  return info ? info.emoji : '⬛';
}

export type { BoardEntry, PlayStatus, StreakEntry };
